CREATE TABLE func (
  id INTEGER PRIMARY KEY, nome VARCHAR(10),
  depto VARCHAR(10), cidade VARCHAR(10));
INSERT INTO func VALUES
  (1, 'Ana', 'TI', 'Natal'),
  (2, 'Beto', 'TI', 'Natal'),
  (3, 'Caio', 'RH', 'Recife'),
  (4, 'Dora', 'TI', 'Natal'),
  (5, 'Edu', 'RH', 'Recife'),
  (6, 'Fabio', 'MKT', 'Natal');
CREATE TABLE departamento AS SELECT DISTINCT depto, cidade FROM func;
SELECT COUNT(*) FROM departamento;

